  /// 画面端から放物線で投げ込まれてバウンドする投てき演出
  throw_,

  /// 雪・桜吹雪・雨・キラキラ・ハート・火の粉などの環境演出
  ambient,
}

/// ワード反応メディア種別
enum MediaKind { image, video, audio }

